BEGIN;

INSERT INTO permission_catalog(permission_code,domain,risk_class,sod_class) VALUES
  ('AI.ACCOUNTING.SETTINGS.VIEW','AI_ACCOUNTING','LOW','READ')
ON CONFLICT(permission_code) DO UPDATE SET active=true,domain=EXCLUDED.domain,risk_class=EXCLUDED.risk_class,sod_class=EXCLUDED.sod_class,version=permission_catalog.version+1,effective_to=NULL;

CREATE FUNCTION refs_wbs_ai_settings_dates_are_valid(p_value jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE item jsonb; item_key text; parsed date;
BEGIN
  CASE jsonb_typeof(p_value)
    WHEN 'array' THEN
      FOR item IN SELECT value FROM jsonb_array_elements(p_value) LOOP
        IF NOT refs_wbs_ai_settings_dates_are_valid(item) THEN RETURN false; END IF;
      END LOOP;
    WHEN 'object' THEN
      FOR item_key,item IN SELECT key,value FROM jsonb_each(p_value) LOOP
        IF item_key=ANY(ARRAY['effective_from','effective_to','completion_date','pis_date','period_start','period_end','cutoff_date','accrual_cutoff_date','prepaid_boundary_date','coverage_start','coverage_end']) AND item<>'null'::jsonb THEN
          IF jsonb_typeof(item)<>'string' THEN RETURN false; END IF;
          BEGIN parsed:=(item#>>'{}')::date; EXCEPTION WHEN SQLSTATE '22007' OR SQLSTATE '22008' THEN RETURN false; END;
          IF to_char(parsed,'YYYY-MM-DD')<>item#>>'{}' THEN RETURN false; END IF;
        ELSIF NOT refs_wbs_ai_settings_dates_are_valid(item) THEN RETURN false;
        END IF;
      END LOOP;
    ELSE
      NULL;
  END CASE;
  RETURN true;
END;
$$;

-- This is a read boundary, not a settings editor.  The parent snapshot binds
-- one entity and one accounting period to the exact approved child snapshots
-- which an AI decision factory may use.  It deliberately never accepts a
-- caller-supplied fallback, version, or hash.
CREATE FUNCTION refs_read_wbs_ai_approved_entity_period_settings(
  p_tenant uuid,p_entity uuid,p_period uuid
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE period_row accounting_period; parent_row setting_snapshot; child_row setting_snapshot; parent_count integer;
  child jsonb; result jsonb; child_key text; child_family text;
  expected_keys constant text[]:=ARRAY[
    'schema_version','company_code','period_id','period_code','period_start','period_end','currency',
    'coa','vendor_treatment','project_property_cost_code','period_close_policy','tax','intercompany','materiality','approval_thresholds','report_mapping','loan_capitalization_policy'
  ];
  child_keys constant text[]:=ARRAY['coa','vendor_treatment','project_property_cost_code','period_close_policy','tax','intercompany','materiality','approval_thresholds','report_mapping','loan_capitalization_policy'];
  child_families constant text[]:=ARRAY[
    'AI_ACCOUNTING_COA_V1','AI_ACCOUNTING_VENDOR_TREATMENT_V1','AI_ACCOUNTING_PROJECT_PROPERTY_COST_CODE_V1','AI_ACCOUNTING_PERIOD_CLOSE_POLICY_V1',
    'AI_ACCOUNTING_TAX_V1','AI_ACCOUNTING_INTERCOMPANY_V1','AI_ACCOUNTING_MATERIALITY_V1','AI_ACCOUNTING_APPROVAL_THRESHOLDS_V1','AI_ACCOUNTING_REPORT_MAPPING_V1','AI_ACCOUNTING_LOAN_CAPITALIZATION_POLICY_V1'
  ];
BEGIN
  PERFORM refs_assert_scope(p_tenant,p_entity,'AI.ACCOUNTING.SETTINGS.VIEW');
  SELECT * INTO period_row FROM accounting_period
   WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AI settings period is not in the requested entity scope' USING ERRCODE='23514'; END IF;

  SELECT count(*) INTO parent_count FROM setting_snapshot
   WHERE tenant_id=p_tenant AND entity_id=p_entity AND family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1'
     AND scope_type='ENTITY' AND scope_key=p_entity::text AND status='APPROVED'
     AND effective_from<=period_row.starts_on::timestamptz
     AND (effective_to IS NULL OR effective_to>period_row.ends_on::timestamptz);
  IF parent_count<>1 THEN RAISE EXCEPTION 'Exactly one approved AI entity-period settings snapshot is required' USING ERRCODE='23514'; END IF;
  SELECT * INTO parent_row FROM setting_snapshot
   WHERE tenant_id=p_tenant AND entity_id=p_entity AND family='AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_V1'
     AND scope_type='ENTITY' AND scope_key=p_entity::text AND status='APPROVED'
     AND effective_from<=period_row.starts_on::timestamptz
     AND (effective_to IS NULL OR effective_to>period_row.ends_on::timestamptz) FOR SHARE;
  IF parent_row.snapshot_hash<>refs_jsonb_hash(parent_row.snapshot)
     OR ARRAY(SELECT jsonb_object_keys(parent_row.snapshot) ORDER BY 1)<>ARRAY(SELECT unnest(expected_keys) ORDER BY 1)
     OR parent_row.snapshot->>'schema_version'<>'AI_ACCOUNTING_ENTITY_PERIOD_SETTINGS_SNAPSHOT_V1'
     OR parent_row.snapshot->>'company_code' !~ '^[A-Z0-9][A-Z0-9_:-]{0,63}$'
     OR parent_row.snapshot->>'period_id'<>p_period::text OR parent_row.snapshot->>'period_code'<>period_row.period_code
     OR parent_row.snapshot->>'period_start'<>period_row.starts_on::text OR parent_row.snapshot->>'period_end'<>period_row.ends_on::text
     OR parent_row.snapshot->>'currency' !~ '^[A-Z]{3}$' THEN
    RAISE EXCEPTION 'Approved AI entity-period settings snapshot is malformed or changed' USING ERRCODE='23514';
  END IF;

  result:=jsonb_build_object(
    'schema_version','WBS_AI_APPROVED_ENTITY_PERIOD_SETTINGS_V1',
    'tenant_id',p_tenant,'entity_id',p_entity,'company_code',parent_row.snapshot->>'company_code',
    'period_id',p_period,'period_code',period_row.period_code,'period_start',period_row.starts_on,'period_end',period_row.ends_on,
    'period_status',period_row.status,'currency',parent_row.snapshot->>'currency','settings_snapshot_id',parent_row.setting_snapshot_id,'settings_version',parent_row.version,
    'settings_hash',parent_row.snapshot_hash,'approval_status','APPROVED','approved_by',parent_row.approved_by,'approved_at',parent_row.approved_at
  );
  FOR child_key,child_family IN SELECT * FROM unnest(child_keys,child_families) LOOP
    child:=parent_row.snapshot->child_key;
    IF jsonb_typeof(child)<>'object'
       OR ARRAY(SELECT jsonb_object_keys(child) ORDER BY 1)<>ARRAY['setting_snapshot_id','snapshot_hash','version']
       OR child->>'setting_snapshot_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR child->>'snapshot_hash' !~ '^sha256:[0-9a-f]{64}$'
       OR child->>'version' !~ '^[1-9][0-9]*$' THEN
      RAISE EXCEPTION 'Approved AI child settings reference is malformed' USING ERRCODE='23514';
    END IF;
    SELECT * INTO child_row FROM setting_snapshot
     WHERE tenant_id=p_tenant AND entity_id=p_entity AND setting_snapshot_id=(child->>'setting_snapshot_id')::uuid
       AND family=child_family AND scope_type='ENTITY' AND scope_key=p_entity::text AND status='APPROVED'
       AND effective_from<=period_row.starts_on::timestamptz AND (effective_to IS NULL OR effective_to>period_row.ends_on::timestamptz)
       FOR SHARE;
    IF NOT FOUND OR child_row.version<>(child->>'version')::bigint OR child_row.snapshot_hash<>child->>'snapshot_hash'
       OR child_row.snapshot_hash<>refs_jsonb_hash(child_row.snapshot) THEN
      RAISE EXCEPTION 'Approved AI child settings snapshot is missing, stale, or changed' USING ERRCODE='23514';
    END IF;
    IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot) ORDER BY 1)<>ARRAY['schema_version','settings']
       OR jsonb_typeof(child_row.snapshot->'settings')<>'object' OR child_row.snapshot->>'schema_version'<>child_family THEN
      RAISE EXCEPTION 'Approved AI child settings schema is unsupported or not closed' USING ERRCODE='23514';
    END IF;
    IF NOT refs_wbs_ai_settings_dates_are_valid(child_row.snapshot->'settings') THEN
      RAISE EXCEPTION 'Approved AI child settings contain an invalid calendar date' USING ERRCODE='23514';
    END IF;
    IF child_key='coa' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['accounts','currency']
         OR child_row.snapshot#>>'{settings,currency}'<>parent_row.snapshot->>'currency'
         OR jsonb_typeof(child_row.snapshot#>'{settings,accounts}')<>'array'
           OR (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}'))<24
           OR (SELECT count(DISTINCT account->>'account_code') FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') account)<>(SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}'))
           OR EXISTS(SELECT 1 FROM unnest(ARRAY['ACCUMULATED_AMORTIZATION','ACCUMULATED_DEPRECIATION','ACCRUED_LIABILITY','AP','AR','CASH','CWIP','CUSTOMER_DEPOSIT_LIABILITY','DEFERRED_REVENUE','EQUITY','ESCROW','EXPENSE','FIXED_ASSET','INTERCOMPANY_CLEARING','INTERCOMPANY_DUE_FROM','INTERCOMPANY_DUE_TO','INTERCOMPANY_ELIMINATION','INTEREST','LOAN','PREPAID','RETAINED_EARNINGS','REVENUE','SECURITY_DEPOSIT_ASSET','TAX_PAYABLE']) required(role) WHERE (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') a WHERE a->>'role'=required.role AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text))<>1)
          OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') account WHERE jsonb_typeof(account)<>'object' OR ARRAY(SELECT jsonb_object_keys(account) ORDER BY 1)<>ARRAY['account_class','account_code','account_type','dimension_requirements','effective_from','effective_to','posting_allowed','role','status'] OR account->>'account_code' !~ '^[A-Z0-9._-]{1,64}$' OR account->>'account_class' NOT IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE') OR account->>'account_type'='' OR jsonb_typeof(account->'dimension_requirements')<>'array' OR jsonb_typeof(account->'posting_allowed')<>'boolean' OR account->>'status' NOT IN ('ACTIVE','INACTIVE') OR account->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (account->>'effective_to' IS NOT NULL AND account->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$') OR (account->>'effective_to' IS NOT NULL AND account->>'effective_from'>account->>'effective_to') OR (account->>'role' IN ('AP','ACCRUED_LIABILITY','LOAN','DEFERRED_REVENUE','TAX_PAYABLE','CUSTOMER_DEPOSIT_LIABILITY','INTERCOMPANY_DUE_TO') AND account->>'account_class'<>'LIABILITY') OR (account->>'role' IN ('AR','CASH','CWIP','ESCROW','PREPAID','FIXED_ASSET','INTERCOMPANY_DUE_FROM','SECURITY_DEPOSIT_ASSET','ACCUMULATED_DEPRECIATION','ACCUMULATED_AMORTIZATION') AND account->>'account_class'<>'ASSET') OR (account->>'role' IN ('EXPENSE','INTEREST') AND account->>'account_class'<>'EXPENSE') OR (account->>'role'='REVENUE' AND account->>'account_class'<>'REVENUE') OR (account->>'role' IN ('EQUITY','RETAINED_EARNINGS','INTERCOMPANY_ELIMINATION') AND account->>'account_class'<>'EQUITY')) THEN RAISE EXCEPTION 'Approved AI COA settings are incomplete' USING ERRCODE='23514'; END IF;
    ELSIF child_key='vendor_treatment' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['default_treatment','vendor_rules']
         OR child_row.snapshot#>>'{settings,default_treatment}'<>'BLOCKED'
         OR jsonb_typeof(child_row.snapshot#>'{settings,vendor_rules}')<>'array'
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v WHERE jsonb_typeof(v)<>'object' OR ARRAY(SELECT jsonb_object_keys(v) ORDER BY 1)<>ARRAY['aliases','contract_keys','duplicate_normalization','effective_from','effective_to','payment_terms_days','recurring','rule_id','service_keys','source_requirements','treatment','vendor_ref'] OR v->>'vendor_ref'='' OR v->>'rule_id'='' OR v->>'treatment' NOT IN ('EXPENSE','PREPAID','ACCRUAL','CWIP','LOAN','REVENUE','DEPOSIT','INTERCOMPANY','REIMBURSEMENT') OR jsonb_typeof(v->'aliases')<>'array' OR jsonb_typeof(v->'contract_keys')<>'array' OR jsonb_typeof(v->'service_keys')<>'array' OR jsonb_typeof(v->'source_requirements')<>'array' OR jsonb_typeof(v->'recurring')<>'boolean' OR jsonb_typeof(v->'duplicate_normalization')<>'boolean' OR v->>'payment_terms_days' !~ '^[0-9]{1,4}$' OR v->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (v->>'effective_to' IS NOT NULL AND v->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$'))
         OR (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}'))<>(SELECT count(DISTINCT v->>'vendor_ref') FROM jsonb_array_elements(child_row.snapshot#>'{settings,vendor_rules}') v) THEN RAISE EXCEPTION 'Approved vendor treatment settings are incomplete or ambiguous' USING ERRCODE='23514'; END IF;
    ELSIF child_key='project_property_cost_code' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['default_capitalization_treatment','dimension_rules'] OR child_row.snapshot#>>'{settings,default_capitalization_treatment}'<>'BLOCKED' OR jsonb_typeof(child_row.snapshot#>'{settings,dimension_rules}')<>'array'
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,dimension_rules}') d WHERE jsonb_typeof(d)<>'object' OR ARRAY(SELECT jsonb_object_keys(d) ORDER BY 1)<>ARRAY['capitalization_treatment','completion_date','cost_code_ref','cwip_account_role','effective_from','effective_to','member_ref','member_requirement','ownership_requirement','pis_date','project_ref','property_ref','rule_id','scope_level','status'] OR d->>'rule_id'='' OR d->>'capitalization_treatment' NOT IN ('EXPENSE','CWIP','BLOCKED') OR d->>'cwip_account_role' NOT IN ('CWIP','FIXED_ASSET','BLOCKED') OR d->>'status' NOT IN ('ACTIVE','COMPLETE','BLOCKED') OR d->>'scope_level' NOT IN ('ENTITY','PROJECT','PROPERTY','COST_CODE','MEMBER','COMBINATION') OR d->>'member_requirement' NOT IN ('REQUIRED','OPTIONAL','FORBIDDEN') OR d->>'ownership_requirement' NOT IN ('REQUIRED','OPTIONAL','FORBIDDEN') OR d->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (d->>'effective_to' IS NOT NULL AND d->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$') OR (d->>'completion_date' IS NOT NULL AND d->>'completion_date' !~ '^\d{4}-\d{2}-\d{2}$') OR (d->>'pis_date' IS NOT NULL AND d->>'pis_date' !~ '^\d{4}-\d{2}-\d{2}$')) THEN RAISE EXCEPTION 'Approved project/property/cost-code settings are incomplete' USING ERRCODE='23514'; END IF;
    ELSIF child_key='period_close_policy' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['accrual_cutoff_date','allow_post','business_calendar','cutoff_date','hard_lock','non_business_dates','override_policy','period_code','period_end','period_id','period_start','period_status','posting_lock','prepaid_boundary_date','prior_period_adjustment_policy','reversal_policy','soft_lock']
         OR child_row.snapshot#>>'{settings,period_status}' NOT IN ('OPEN','SOFT_CLOSED','CLOSED') OR jsonb_typeof(child_row.snapshot#>'{settings,allow_post}')<>'boolean'
         OR jsonb_typeof(child_row.snapshot#>'{settings,posting_lock}')<>'boolean' OR jsonb_typeof(child_row.snapshot#>'{settings,hard_lock}')<>'boolean' OR jsonb_typeof(child_row.snapshot#>'{settings,soft_lock}')<>'boolean' OR jsonb_typeof(child_row.snapshot#>'{settings,non_business_dates}')<>'array' OR child_row.snapshot#>>'{settings,business_calendar}'='' OR child_row.snapshot#>>'{settings,reversal_policy}' NOT IN ('NONE','NEXT_OPEN_PERIOD','BLOCKED') OR child_row.snapshot#>>'{settings,prior_period_adjustment_policy}' NOT IN ('BLOCKED','CONTROLLER_ONLY') OR child_row.snapshot#>>'{settings,override_policy}' NOT IN ('BLOCKED','CONTROLLER_ONLY') OR child_row.snapshot#>>'{settings,period_id}'<>p_period::text OR child_row.snapshot#>>'{settings,period_code}'<>period_row.period_code OR child_row.snapshot#>>'{settings,period_start}'<>period_row.starts_on::text OR child_row.snapshot#>>'{settings,period_end}'<>period_row.ends_on::text OR child_row.snapshot#>>'{settings,cutoff_date}' !~ '^\d{4}-\d{2}-\d{2}$' OR child_row.snapshot#>>'{settings,accrual_cutoff_date}' !~ '^\d{4}-\d{2}-\d{2}$' OR child_row.snapshot#>>'{settings,prepaid_boundary_date}' !~ '^\d{4}-\d{2}-\d{2}$' OR child_row.snapshot#>>'{settings,period_status}'<>period_row.status::text OR (child_row.snapshot#>>'{settings,period_status}'='OPEN' AND ((child_row.snapshot#>>'{settings,allow_post}')<>'true' OR (child_row.snapshot#>>'{settings,posting_lock}')<>'false' OR (child_row.snapshot#>>'{settings,hard_lock}')<>'false' OR (child_row.snapshot#>>'{settings,soft_lock}')<>'false')) OR (child_row.snapshot#>>'{settings,period_status}'='SOFT_CLOSED' AND ((child_row.snapshot#>>'{settings,allow_post}')<>'false' OR (child_row.snapshot#>>'{settings,posting_lock}')<>'true' OR (child_row.snapshot#>>'{settings,hard_lock}')<>'false' OR (child_row.snapshot#>>'{settings,soft_lock}')<>'true')) OR (child_row.snapshot#>>'{settings,period_status}'='CLOSED' AND ((child_row.snapshot#>>'{settings,allow_post}')<>'false' OR (child_row.snapshot#>>'{settings,posting_lock}')<>'true' OR (child_row.snapshot#>>'{settings,hard_lock}')<>'true' OR (child_row.snapshot#>>'{settings,soft_lock}')<>'false')) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(child_row.snapshot#>'{settings,non_business_dates}') d WHERE d !~ '^\d{4}-\d{2}-\d{2}$') THEN RAISE EXCEPTION 'Approved period close policy is incomplete' USING ERRCODE='23514'; END IF;
    ELSIF child_key='tax' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['accrual_account_role','allocation_method','allocation_precision','coverage_end','coverage_start','effective_from','effective_to','expense_account_role','jurisdiction','prepaid_account_role','residual_rule','tax_codes','treatment'] OR child_row.snapshot#>>'{settings,jurisdiction}'='' OR child_row.snapshot#>>'{settings,treatment}' NOT IN ('GROSS','NET','BLOCKED') OR child_row.snapshot#>>'{settings,allocation_method}' NOT IN ('STRAIGHT_LINE_DAILY','SOURCE_PERIOD','BLOCKED') OR child_row.snapshot#>>'{settings,allocation_precision}' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$' OR child_row.snapshot#>>'{settings,residual_rule}' NOT IN ('EXPENSE','PREPAID','ACCRUAL','BLOCKED') OR child_row.snapshot#>>'{settings,expense_account_role}' NOT IN ('EXPENSE','PREPAID','ACCRUED_LIABILITY','BLOCKED') OR child_row.snapshot#>>'{settings,prepaid_account_role}' NOT IN ('PREPAID','BLOCKED') OR child_row.snapshot#>>'{settings,accrual_account_role}' NOT IN ('ACCRUED_LIABILITY','BLOCKED') OR jsonb_typeof(child_row.snapshot#>'{settings,tax_codes}')<>'array' OR child_row.snapshot#>>'{settings,coverage_start}' !~ '^\d{4}-\d{2}-\d{2}$' OR child_row.snapshot#>>'{settings,coverage_end}' !~ '^\d{4}-\d{2}-\d{2}$' OR child_row.snapshot#>>'{settings,coverage_start}'>period_row.starts_on::text OR child_row.snapshot#>>'{settings,coverage_end}'<period_row.ends_on::text OR child_row.snapshot#>>'{settings,effective_from}' !~ '^\d{4}-\d{2}-\d{2}$' OR (child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_to}' !~ '^\d{4}-\d{2}-\d{2}$') OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,tax_codes}') t WHERE jsonb_typeof(t)<>'object' OR ARRAY(SELECT jsonb_object_keys(t) ORDER BY 1)<>ARRAY['basis','code','effective_from','effective_to','evidence_requirements','expense_treatment','rate','recoverability'] OR t->>'code'='' OR t->>'rate' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$' OR t->>'basis' NOT IN ('GROSS','NET','BLOCKED') OR t->>'recoverability' NOT IN ('RECOVERABLE','NON_RECOVERABLE','BLOCKED') OR t->>'expense_treatment' NOT IN ('EXPENSE','ASSET','BLOCKED') OR jsonb_typeof(t->'evidence_requirements')<>'array' OR t->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (t->>'effective_to' IS NOT NULL AND t->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$')) THEN RAISE EXCEPTION 'Approved tax settings are incomplete' USING ERRCODE='23514'; END IF;
    ELSIF child_key='intercompany' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['clearing_account_role','enabled','entities'] OR jsonb_typeof(child_row.snapshot#>'{settings,enabled}')<>'boolean' OR child_row.snapshot#>>'{settings,clearing_account_role}' NOT IN ('INTERCOMPANY_CLEARING','BLOCKED') OR jsonb_typeof(child_row.snapshot#>'{settings,entities}')<>'array' OR (child_row.snapshot#>>'{settings,enabled}'='false' AND ((child_row.snapshot#>>'{settings,clearing_account_role}')<>'BLOCKED' OR jsonb_array_length(child_row.snapshot#>'{settings,entities}')<>0)) OR (child_row.snapshot#>>'{settings,enabled}'='true' AND jsonb_array_length(child_row.snapshot#>'{settings,entities}')=0) OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,entities}') i WHERE jsonb_typeof(i)<>'object' OR ARRAY(SELECT jsonb_object_keys(i) ORDER BY 1)<>ARRAY['company_code','counterparty_approval_hash','counterparty_approval_id','counterparty_entity_id','currency','dimension_requirements','due_from_account_role','due_to_account_role','effective_from','effective_to','elimination_account_role'] OR i->>'company_code'='' OR i->>'counterparty_entity_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR i->>'counterparty_approval_id' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR i->>'counterparty_approval_hash' !~ '^sha256:[0-9a-f]{64}$' OR i->>'currency' !~ '^[A-Z]{3}$' OR jsonb_typeof(i->'dimension_requirements')<>'array' OR i->>'due_to_account_role'<>'INTERCOMPANY_DUE_TO' OR i->>'due_from_account_role'<>'INTERCOMPANY_DUE_FROM' OR i->>'elimination_account_role'<>'INTERCOMPANY_ELIMINATION' OR i->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (i->>'effective_to' IS NOT NULL AND i->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$')) THEN RAISE EXCEPTION 'Approved intercompany settings are incomplete' USING ERRCODE='23514'; END IF;
    ELSIF child_key='materiality' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['amount_drop_ratio','amount_drop_window_days','ap_aging_amount','ap_stale_days','balance_dormant_days','budget_variance_amount','currency','duplicate_amount','effective_from','effective_to','financial_statement_amount','loan_difference_amount','loan_excess_draw_amount','manual_je_amount','manual_round_amount','minimum_absolute_balance','minimum_open_amount','near_duplicate_amount','vendor_frequency_count','vendor_frequency_window_days'] OR child_row.snapshot#>>'{settings,currency}'<>parent_row.snapshot->>'currency' OR EXISTS(SELECT 1 FROM jsonb_each_text(child_row.snapshot->'settings') e WHERE e.key NOT IN ('currency','effective_from','effective_to','ap_stale_days','balance_dormant_days','amount_drop_window_days','vendor_frequency_count','vendor_frequency_window_days','amount_drop_ratio') AND e.value !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$') OR child_row.snapshot#>>'{settings,amount_drop_ratio}' !~ '^0\.\d{4}$|^1\.0000$' OR child_row.snapshot#>>'{settings,ap_stale_days}' !~ '^[0-9]+$' OR child_row.snapshot#>>'{settings,balance_dormant_days}' !~ '^[0-9]+$' OR child_row.snapshot#>>'{settings,amount_drop_window_days}' !~ '^[1-9][0-9]*$' OR child_row.snapshot#>>'{settings,vendor_frequency_count}' !~ '^[1-9][0-9]*$' OR child_row.snapshot#>>'{settings,vendor_frequency_window_days}' !~ '^[1-9][0-9]*$' OR child_row.snapshot#>>'{settings,effective_from}' !~ '^\d{4}-\d{2}-\d{2}$' OR (child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_to}' !~ '^\d{4}-\d{2}-\d{2}$') THEN RAISE EXCEPTION 'Approved materiality settings are incomplete' USING ERRCODE='23514'; END IF;
    ELSIF child_key='approval_thresholds' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['accrual_amount_threshold','approval_levels','classification_thresholds','currency','cwip_amount_threshold','expense_amount_threshold','prepaid_amount_threshold'] OR child_row.snapshot#>>'{settings,currency}'<>parent_row.snapshot->>'currency' OR jsonb_typeof(child_row.snapshot#>'{settings,approval_levels}')<>'array' OR jsonb_array_length(child_row.snapshot#>'{settings,approval_levels}')<>4 OR jsonb_typeof(child_row.snapshot#>'{settings,classification_thresholds}')<>'array' OR jsonb_array_length(child_row.snapshot#>'{settings,classification_thresholds}')<>15 OR EXISTS(SELECT 1 FROM jsonb_each_text(child_row.snapshot->'settings') e WHERE e.key NOT IN ('currency','approval_levels','classification_thresholds') AND e.value !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$') OR ARRAY(SELECT a->>'action' FROM jsonb_array_elements(child_row.snapshot#>'{settings,approval_levels}') a ORDER BY 1)<>ARRAY['APPROVE','DRAFT','POST','REVIEW'] OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,approval_levels}') a WHERE jsonb_typeof(a)<>'object' OR ARRAY(SELECT jsonb_object_keys(a) ORDER BY 1)<>ARRAY['action','approver_role','confidence_band','effective_from','effective_to','maximum_amount','minimum_amount','override_policy','poster_role','preparer_role','reviewer_role','risk_band','sod_constraints','submit_permission','submitter_role','workflow'] OR a->>'action' NOT IN ('DRAFT','REVIEW','APPROVE','POST') OR a->>'risk_band' NOT IN ('LOW','MEDIUM','HIGH','BLOCKED') OR a->>'confidence_band' NOT IN ('LOW','MEDIUM','HIGH') OR a->>'override_policy' NOT IN ('BLOCKED','CONTROLLER_ONLY') OR jsonb_typeof(a->'sod_constraints')<>'array' OR jsonb_array_length(a->'sod_constraints')=0 OR a->>'workflow'='' OR a->>'preparer_role'='' OR a->>'reviewer_role'='' OR a->>'approver_role'='' OR a->>'poster_role'='' OR a->>'submitter_role'<>a->>'preparer_role' OR a->>'submit_permission'<>'GL.JE.SUBMIT' OR a->>'preparer_role' ~* '^AI_' OR a->>'reviewer_role' ~* '^AI_' OR a->>'approver_role' ~* '^AI_' OR a->>'poster_role' ~* '^AI_' OR cardinality(ARRAY(SELECT DISTINCT x FROM unnest(ARRAY[a->>'preparer_role',a->>'reviewer_role',a->>'approver_role',a->>'poster_role']) x))<>4 OR a->>'minimum_amount' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$' OR a->>'maximum_amount' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$' OR (a->>'minimum_amount')::numeric>(a->>'maximum_amount')::numeric OR a->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (a->>'effective_to' IS NOT NULL AND a->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$')) OR (SELECT count(DISTINCT (a->>'workflow',a->>'preparer_role',a->>'reviewer_role',a->>'approver_role',a->>'poster_role',a->>'submitter_role',a->>'submit_permission')) FROM jsonb_array_elements(child_row.snapshot#>'{settings,approval_levels}') a)<>1 OR ARRAY(SELECT c->>'classification' FROM jsonb_array_elements(child_row.snapshot#>'{settings,classification_thresholds}') c ORDER BY 1)<>ARRAY['ACCRUAL','CAPITALIZATION','CLOSING_COST','DEPOSIT','EXPENSE','FIXED_ASSET','INTERCOMPANY','LOAN','PAYMENT','PREPAID','RECLASS','REIMBURSEMENT','REVENUE','REVERSAL','TAX'] OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,classification_thresholds}') c WHERE jsonb_typeof(c)<>'object' OR ARRAY(SELECT jsonb_object_keys(c) ORDER BY 1)<>ARRAY['classification','confidence_band','effective_from','effective_to','maximum_amount','minimum_amount','risk_band','workflow'] OR c->>'risk_band' NOT IN ('LOW','MEDIUM','HIGH','BLOCKED') OR c->>'confidence_band' NOT IN ('LOW','MEDIUM','HIGH') OR c->>'workflow' NOT IN ('STANDARD','ELEVATED','CONTROLLER') OR c->>'minimum_amount' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$' OR c->>'maximum_amount' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$' OR (c->>'minimum_amount')::numeric>(c->>'maximum_amount')::numeric OR c->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (c->>'effective_to' IS NOT NULL AND c->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$')) THEN RAISE EXCEPTION 'Approved approval-threshold settings are incomplete' USING ERRCODE='23514'; END IF;
    END IF;
    IF child_key='coa' AND EXISTS(
      SELECT 1
      FROM jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') WITH ORDINALITY a(account,ordinality)
      JOIN jsonb_array_elements(child_row.snapshot#>'{settings,accounts}') WITH ORDINALITY b(account,ordinality)
        ON a.ordinality<b.ordinality AND a.account->>'role'=b.account->>'role'
       AND a.account->>'effective_from'<=COALESCE(b.account->>'effective_to','9999-12-31')
       AND b.account->>'effective_from'<=COALESCE(a.account->>'effective_to','9999-12-31')
    ) THEN RAISE EXCEPTION 'Approved AI COA settings have overlapping role effectivity' USING ERRCODE='23514'; END IF;
    IF child_key='approval_thresholds' AND EXISTS(
      SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,approval_levels}') a
      WHERE ARRAY(SELECT jsonb_array_elements_text(a->'sod_constraints') ORDER BY 1)
        <>ARRAY['APPROVER_NE_POSTER','PREPARER_NE_APPROVER','PREPARER_NE_POSTER','PREPARER_NE_REVIEWER','REVIEWER_NE_APPROVER','REVIEWER_NE_POSTER']
    ) THEN RAISE EXCEPTION 'Approved approval-threshold SoD policy is incomplete' USING ERRCODE='23514'; END IF;
    IF child_key='approval_thresholds' AND EXISTS(
      SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,classification_thresholds}') c
      WHERE c->>'effective_from'>period_row.starts_on::text OR (c->>'effective_to' IS NOT NULL AND c->>'effective_to'<period_row.ends_on::text) OR (c->>'effective_to' IS NOT NULL AND c->>'effective_from'>c->>'effective_to')
    ) THEN RAISE EXCEPTION 'Approved classification threshold does not cover the selected period' USING ERRCODE='23514'; END IF;
    IF child_key='loan_capitalization_policy' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['capitalization_start_policy','cessation_policy','currency','cwip_account_role','effective_from','effective_to','eligible_fee_policy','eligible_interest_policy','expense_account_role','fixed_asset_account_role','loan_purpose','materiality_amount','qualifying_combinations','required_evidence','suspension_policy']
         OR child_row.snapshot#>>'{settings,currency}'<>parent_row.snapshot->>'currency'
         OR child_row.snapshot#>>'{settings,loan_purpose}' NOT IN ('QUALIFYING_ASSET_ONLY','BLOCKED')
         OR child_row.snapshot#>>'{settings,capitalization_start_policy}' NOT IN ('WHEN_QUALIFYING_ACTIVITY_STARTS','BLOCKED')
         OR child_row.snapshot#>>'{settings,suspension_policy}' NOT IN ('PAUSE_DURING_EXTENDED_SUSPENSION','BLOCKED')
         OR child_row.snapshot#>>'{settings,cessation_policy}' NOT IN ('ON_READY_FOR_INTENDED_USE','BLOCKED')
         OR child_row.snapshot#>>'{settings,eligible_interest_policy}' NOT IN ('ACTUAL_INTEREST','BLOCKED')
         OR child_row.snapshot#>>'{settings,eligible_fee_policy}' NOT IN ('DIRECT_FEES_ONLY','BLOCKED')
         OR child_row.snapshot#>>'{settings,expense_account_role}' NOT IN ('EXPENSE','BLOCKED')
         OR child_row.snapshot#>>'{settings,cwip_account_role}' NOT IN ('CWIP','BLOCKED')
         OR child_row.snapshot#>>'{settings,fixed_asset_account_role}' NOT IN ('FIXED_ASSET','BLOCKED')
         OR child_row.snapshot#>>'{settings,materiality_amount}' !~ '^(0|[1-9][0-9]{0,15})\.[0-9]{4}$'
         OR jsonb_typeof(child_row.snapshot#>'{settings,qualifying_combinations}')<>'array' OR jsonb_array_length(child_row.snapshot#>'{settings,qualifying_combinations}')=0
         OR jsonb_typeof(child_row.snapshot#>'{settings,required_evidence}')<>'array' OR jsonb_array_length(child_row.snapshot#>'{settings,required_evidence}')=0
         OR child_row.snapshot#>>'{settings,effective_from}' !~ '^\d{4}-\d{2}-\d{2}$'
         OR (child_row.snapshot#>>'{settings,effective_to}' IS NOT NULL AND child_row.snapshot#>>'{settings,effective_to}' !~ '^\d{4}-\d{2}-\d{2}$')
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,qualifying_combinations}') q WHERE jsonb_typeof(q)<>'object' OR ARRAY(SELECT jsonb_object_keys(q) ORDER BY 1)<>ARRAY['asset_ref','effective_from','effective_to','project_ref','property_ref'] OR q->>'asset_ref' IS NOT NULL OR (q->>'project_ref' IS NULL AND q->>'property_ref' IS NULL) OR q->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (q->>'effective_to' IS NOT NULL AND q->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$') OR NOT EXISTS(SELECT 1 FROM setting_snapshot dimension_row JOIN LATERAL jsonb_array_elements(dimension_row.snapshot#>'{settings,dimension_rules}') d ON true WHERE dimension_row.tenant_id=p_tenant AND dimension_row.entity_id=p_entity AND dimension_row.setting_snapshot_id=(parent_row.snapshot#>>'{project_property_cost_code,setting_snapshot_id}')::uuid AND d->>'status'='ACTIVE' AND d->>'capitalization_treatment'='CWIP' AND d->>'ownership_requirement'<>'FORBIDDEN' AND d->>'project_ref' IS NOT DISTINCT FROM q->>'project_ref' AND d->>'property_ref' IS NOT DISTINCT FROM q->>'property_ref' AND (d->>'completion_date' IS NULL OR d->>'completion_date'>=period_row.starts_on::text) AND (d->>'pis_date' IS NULL OR d->>'pis_date'>=period_row.starts_on::text))) THEN RAISE EXCEPTION 'Approved loan capitalization policy is incomplete' USING ERRCODE='23514'; END IF;
    END IF;
    IF child_key='report_mapping' THEN
      IF ARRAY(SELECT jsonb_object_keys(child_row.snapshot->'settings') ORDER BY 1)<>ARRAY['account_mappings','currency']
         OR child_row.snapshot#>>'{settings,currency}'<>parent_row.snapshot->>'currency'
         OR jsonb_typeof(child_row.snapshot#>'{settings,account_mappings}')<>'array'
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE jsonb_typeof(m)<>'object' OR ARRAY(SELECT jsonb_object_keys(m) ORDER BY 1)<>ARRAY['account_code','account_role','cash_flow_class','contra','effective_from','effective_to','normal_balance','report_row_code','statement'] OR m->>'account_code' !~ '^[A-Z0-9._-]{1,64}$' OR m->>'account_role'='' OR m->>'statement' NOT IN ('BS','IS') OR m->>'normal_balance' NOT IN ('DEBIT','CREDIT') OR jsonb_typeof(m->'contra')<>'boolean' OR m->>'cash_flow_class' NOT IN ('OPERATING','INVESTING','FINANCING','NON_CASH') OR m->>'report_row_code'='' OR m->>'effective_from' !~ '^\d{4}-\d{2}-\d{2}$' OR (m->>'effective_to' IS NOT NULL AND m->>'effective_to' !~ '^\d{4}-\d{2}-\d{2}$') OR (m->>'effective_to' IS NOT NULL AND m->>'effective_from'>m->>'effective_to')) THEN RAISE EXCEPTION 'Approved report mapping is incomplete or ambiguous' USING ERRCODE='23514'; END IF;
      IF (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE m->>'effective_from'<=period_row.starts_on::text AND (m->>'effective_to' IS NULL OR m->>'effective_to'>=period_row.ends_on::text))<>(SELECT count(*) FROM setting_snapshot coa_row JOIN LATERAL jsonb_array_elements(coa_row.snapshot#>'{settings,accounts}') a ON true WHERE coa_row.tenant_id=p_tenant AND coa_row.entity_id=p_entity AND coa_row.setting_snapshot_id=(parent_row.snapshot#>>'{coa,setting_snapshot_id}')::uuid AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text)) OR EXISTS(SELECT 1 FROM setting_snapshot coa_row JOIN LATERAL jsonb_array_elements(coa_row.snapshot#>'{settings,accounts}') a ON true WHERE coa_row.tenant_id=p_tenant AND coa_row.entity_id=p_entity AND coa_row.setting_snapshot_id=(parent_row.snapshot#>>'{coa,setting_snapshot_id}')::uuid AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text) AND (SELECT count(*) FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE m->>'account_code'=a->>'account_code' AND m->>'account_role'=a->>'role' AND m->>'effective_from'<=period_row.starts_on::text AND (m->>'effective_to' IS NULL OR m->>'effective_to'>=period_row.ends_on::text))<>1) OR EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE m->>'effective_from'<=period_row.starts_on::text AND (m->>'effective_to' IS NULL OR m->>'effective_to'>=period_row.ends_on::text) AND NOT EXISTS(SELECT 1 FROM setting_snapshot coa_row JOIN LATERAL jsonb_array_elements(coa_row.snapshot#>'{settings,accounts}') a ON true WHERE coa_row.tenant_id=p_tenant AND coa_row.entity_id=p_entity AND coa_row.setting_snapshot_id=(parent_row.snapshot#>>'{coa,setting_snapshot_id}')::uuid AND a->>'account_code'=m->>'account_code' AND a->>'role'=m->>'account_role' AND a->>'status'='ACTIVE' AND a->>'posting_allowed'='true' AND a->>'effective_from'<=period_row.starts_on::text AND (a->>'effective_to' IS NULL OR a->>'effective_to'>=period_row.ends_on::text))) THEN RAISE EXCEPTION 'Approved report mapping does not bind the approved COA' USING ERRCODE='23514'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_array_elements(child_row.snapshot#>'{settings,account_mappings}') m WHERE (m->>'account_role' IN ('AP','ACCRUED_LIABILITY','LOAN','DEFERRED_REVENUE','TAX_PAYABLE','CUSTOMER_DEPOSIT_LIABILITY','INTERCOMPANY_DUE_TO') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'false')) OR (m->>'account_role' IN ('AR','CASH','CWIP','ESCROW','PREPAID','FIXED_ASSET','INTERCOMPANY_DUE_FROM','SECURITY_DEPOSIT_ASSET') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'DEBIT' OR m->>'contra'<>'false')) OR (m->>'account_role' IN ('ACCUMULATED_DEPRECIATION','ACCUMULATED_AMORTIZATION') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'true')) OR (m->>'account_role' IN ('EXPENSE','INTEREST') AND (m->>'statement'<>'IS' OR m->>'normal_balance'<>'DEBIT' OR m->>'contra'<>'false')) OR (m->>'account_role'='REVENUE' AND (m->>'statement'<>'IS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'false')) OR (m->>'account_role' IN ('EQUITY','RETAINED_EARNINGS','INTERCOMPANY_ELIMINATION') AND (m->>'statement'<>'BS' OR m->>'normal_balance'<>'CREDIT' OR m->>'contra'<>'false'))) THEN RAISE EXCEPTION 'Approved report mapping violates COA role semantics' USING ERRCODE='23514'; END IF;
    END IF;
    result:=result||jsonb_build_object(child_key,jsonb_build_object('tenant_id',p_tenant,'entity_id',p_entity,'period_id',p_period,'setting_snapshot_id',child_row.setting_snapshot_id,'version',child_row.version,'snapshot_hash',child_row.snapshot_hash,'schema_version',child_row.snapshot->>'schema_version','approval_status','APPROVED','approved_by',child_row.approved_by,'approved_at',child_row.approved_at,'settings',child_row.snapshot->'settings'));
  END LOOP;
  RETURN result||jsonb_build_object('can_create_draft',false,'can_review',false,'can_approve',false,'can_post',false);
END;
$$;

REVOKE ALL ON FUNCTION refs_read_wbs_ai_approved_entity_period_settings(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_read_wbs_ai_approved_entity_period_settings(uuid,uuid,uuid) TO refs_app;

COMMIT;
